package com.smarthealth.dao;
import com.zaxxer.hikari.*;import java.sql.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Small Hikari-backed JDBC connection pool for the local H2 database. */ public final class ConnectionManager implements AutoCloseable{private final HikariDataSource source;public ConnectionManager(String url){HikariConfig c=new HikariConfig();c.setJdbcUrl(url);c.setUsername("sa");c.setPassword("");c.setMaximumPoolSize(8);source=new HikariDataSource(c);}public Connection getConnection()throws SQLException{return source.getConnection();}public void initialize(){try(Connection c=getConnection();Statement s=c.createStatement();InputStream in=getClass().getResourceAsStream("/schema.sql")){if(in==null)throw new IllegalStateException("schema.sql missing");String sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);for(String part:sql.split(";"))if(!part.isBlank())s.execute(part.trim());}catch(Exception e){throw new com.smarthealth.exception.DataAccessException("Could not initialize database",e);}}@Override public void close(){source.close();}}
